export function buildFinancingDebtSchedule(startISO = null) {
  return buildScheduleFor(FINANCING_DEBT_MODULES, startISO, FINANCING_DEBT_META.cadenceDays);
}

export function financingDebtProgressSummary(progress = {}) {
  return progressSummaryFor(FINANCING_DEBT_MODULES, progress);
}

export function exportFinancingDebtCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: FINANCING_DEBT_META,
    modules: buildFinancingDebtSchedule(startISO),
    sessionFlow: FINANCING_DEBT_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function financingDebtRefs() {
  const seen = new Set();
  for (const m of FINANCING_DEBT_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((FINANCING_DEBT_META.wordFirst && FINANCING_DEBT_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

